mapper.select:
select r.warning_id, r.rule_id, r.student_id, r.subject_id, r.knowledge_id, r.paper_id,
       r.level, r.title, r.content, r.metric_value, r.status, r.handle_by, r.handle_time,
       r.handle_remark, r.create_time, s.student_name, s.student_no, wr.rule_name
from spas_warning_record r
left join spas_student s on s.student_id = r.student_id
left join spas_warning_rule wr on wr.rule_id = r.rule_id

    AND r.student_id = #{studentId}
    AND r.rule_id = #{ruleId}
    AND r.status = #{status}
    AND r.level = #{level}
    AND s.student_name like concat('%', #{studentName,jdbcType=VARCHAR}, '%')
    AND s.student_no like concat('%', #{studentNo,jdbcType=VARCHAR}, '%')


            AND s.dept_id in
            #{did}

        ${params.dataScope}


order by r.create_time desc

mapper.update:
update spas_warning_record
status = #{status}, handle_by = #{handleBy}, handle_time = #{handleTime}, handle_remark = #{handleRemark}, metric_value = #{metricValue}, content = #{content},
where warning_id = #{warningId}
